-- Create "config_revisions" table
CREATE TABLE `config_revisions` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `team_id` varchar(32) NOT NULL, `config_id` varchar(32) NOT NULL, `version` bigint NOT NULL, `kind` enum('model','preset','plugin') NOT NULL, `name` varchar(480) NOT NULL, `data` json NOT NULL, `author_id` varchar(32) NOT NULL DEFAULT "", `reviewer_id` varchar(32) NOT NULL DEFAULT "", `note` varchar(8000) NOT NULL DEFAULT "", `source` enum('system','legacy','direct','approved') NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `configrevision_team_id_config_id_version` (`team_id`, `config_id`, `version`), INDEX `configrevision_team_id_created_at` (`team_id`, `created_at`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "resource_submissions" table
CREATE TABLE `resource_submissions` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `updated_at` datetime(6) NOT NULL, `team_id` varchar(32) NOT NULL, `author_id` varchar(32) NOT NULL, `config_id` varchar(32) NOT NULL, `base_version` bigint NOT NULL DEFAULT 0, `proposal` json NOT NULL, `note` varchar(8000) NOT NULL DEFAULT "", `state` enum('draft','pending','published','rejected','withdrawn') NOT NULL DEFAULT "draft", `revision` bigint NOT NULL DEFAULT 1, `reviewer_id` varchar(32) NOT NULL DEFAULT "", `reason` varchar(8000) NOT NULL DEFAULT "", `decided_at` datetime(6) NULL, PRIMARY KEY (`id`), INDEX `resourcesubmission_team_id_author_id` (`team_id`, `author_id`), INDEX `resourcesubmission_team_id_state` (`team_id`, `state`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
